    "judgmentZh": "元亨，利牝马之贞。君子有攸往，先迷失道，后顺得常。西南得朋，东北丧朋。安贞吉。",
    "judgmentEn": "Sublime success, furthering through the perseverance of a mare. If the noble person undertakes something, going first leads astray; following finds guidance. Southwest finds friends; Northeast loses friends. Quiet perseverance brings good fortune.",
    "tuanZh": "《彖》曰：大哉坤为地，刚柔应而万物资始。",
    "tuanEn": "Tuan: Sublime is The Receptive Earth, where yin and yang harmonize to engender prosperity.",
    "greatXiangZh": "地势坤，君子以厚德载物。",
    "greatXiangEn": "The earth's condition is receptive devotion; thus the noble person carries the world with generous virtue.",
