    "modernInterpretation": {
      "philosophyZh": "卦名【坤为地】，卦象由坤（地）与坤（地）上下相合而成，至纯至柔，大地无疆。核心重点在于【柔顺承载与深沉积累】——厚德载物，以退为进，象征生化万物之母性能量；重在接纳、包容、守静与深度支持，先迷失而后得主；顺应客观规律，以沉静定力托举全局。",
      "philosophyEn": "[Core Focus: Receptive Grounding & Supportive Endurance]: Pure Yin Earth over Earth. Prime directive: master the power of receptive adaptation, profound endurance, and steadfast execution. Lead by serving the whole and letting reality ripen organically.",
      "careerZh": "适合担任核心统筹、幕后推手、专业合伙人或运营支持；先随从顺应而后主导，切忌争强斗狠抢风头。",
      "careerEn": "Thrive as the operational anchor, behind-the-scenes strategist, or trusted partner; align with capable leadership rather than premature front-running.",
      "wealthZh": "以守为攻、稳健复利；利于实体资产、资源整合、土地房产与长期运营，忌投机博弈与冒进。",
      "wealthEn": "Defensive capital preservation and tangible asset accumulation; excel in resource integration and recurring-yield vehicles.",
      "relationshipZh": "温柔体贴、包容宽厚是感情长久的基石；多倾听对方心声，以柔克刚，以德化人，家和万事兴。",
      "relationshipEn": "Empathy and spacious patience dissolve domestic tension; nurture trust through steadfast loyalty and unhurried emotional support.",
      "actionGuidanceZh": "【宜】：含蓄修身、厚待他人、顺应规律、踏实执行。【忌】：急功近利、主次颠倒、刚愎自扰、轻举妄动。",
      "actionGuidanceEn": "[Favorable]: Receptive patience, generous tolerance, disciplined execution. [Taboo]: Impatient rushing, usurping roles, rigid obstinacy."
    }
