      "philosophyZh": "卦名【水雷屯】，卦象由坎（水）与震（雷）上下相合而成，云雷翻滚，破土逢阻。核心重点在于【初创破局与耐受混沌】——如同种子突破坚硬冻土，前路虽充满险阻与不确定性，但内蕴磅礴生机；核心在于广结贤才、搭建基础架构、小步试错；切忌盲动扩张，在混沌中保持最高战略定力。",
      "philosophyEn": "[Core Focus: Seed Inception & Navigating Early Chaos]: Upper Water over lower Thunder. Prime directive: endure the initial friction of new ventures. Focus on recruiting trusted talent, setting basic rules, and building durable roots before visible expansion.",
