      "actionGuidanceZh": "【宜】：广结善缘、设立制度、夯实根基、小步迭代。【忌】：盲动出击、急躁冒进、孤家寡人、丧失耐心。",
      "actionGuidanceEn": "[Favorable]: Building coalitions, codifying fundamentals, patient iterations. [Taboo]: Reckless leaps, premature scale, isolating oneself."
