    "modernInterpretation": {
      "philosophyZh": "卦名【水天需】，卦象由坎（水）与乾（天）上下相合而成，云升于天，待雨而降。核心重点在于【战略等待与从容积蓄】——眼前险阻横亘于前，大势尚未成熟；君子当饮食宴乐、从容休整身心，静待天地阴阳化雨之契机；切忌心浮气躁、强行突破，耐得住寂寞方能接得住大运。",
      "philosophyEn": "[Core Focus: Strategic Patience & Somatic Replenishment]: Upper Water over lower Heaven. Prime directive: wait with poised equanimity when conditions are not yet ripe. Replenish energy, enjoy life, and avoid forced breakthroughs until the tide turns.",
      "careerZh": "外部阻力较大时不必硬冲硬闯，利用缓冲期复盘复健、优化工作流，时机一至立即顺水推舟。",
      "careerEn": "When external headwinds stall execution, refrain from battering the door; use this pause to streamline systems and sharpen tools.",
      "wealthZh": "现金为王、守口如瓶，耐心等待被低估的确定性超级良机出现，绝不赚急功近利之险钱。",
      "wealthEn": "Cash is king; maintain high liquidity and wait patiently for asymmetric, mispriced opportunities to present themselves.",
      "relationshipZh": "给彼此留出沉淀与自我成长的呼吸空间，不急于要求对方给出长远承诺，顺其自然花开水到。",
      "relationshipEn": "Grant the relationship spacious breathing room; allow emotional bonds to deepen organically without forcing ultimatums.",
      "actionGuidanceZh": "【宜】：安常处顺、养精蓄锐、充实内力、从容守时。【忌】：急火攻心、焦虑内耗、铤而走险、强行推进。",
      "actionGuidanceEn": "[Favorable]: Poised replenishment, disciplined waiting, conserving capital. [Taboo]: Agitated fretting, reckless gambits, forcing timing."
    }
