    "modernInterpretation": {
      "philosophyZh": "卦名【天水讼】，卦象由乾（天）与坎（水）上下相合而成，天上一水地下，相悖而行。核心重点在于【争端平息与止讼慎和】——诉求不合、摩擦激化，极易陷入旷日持久的利益撕扯与名利损耗；君子作事谋始，行事以和为贵、适可而止；切忌逞一时口舌之快或死磕到底，退让妥协反得清安。",
      "philosophyEn": "[Core Focus: Conflict De-escalation & Principled Compromise]: Upper Heaven over lower Water. Prime directive: halt litigation, contract feuds, and interpersonal disputes early. Victory through stubborn contention breeds mutual ruin; seek mediated settlements.",
      "careerZh": "职场若有利益冲突或部门分歧，切忌升级为公开对抗；厘清职责边界，必要时引入第三方仲裁化解。",
      "careerEn": "Avoid escalating departmental friction into open warfare; clarify jurisdictional boundaries and engage objective mediators.",
      "wealthZh": "严格防范合同漏洞、法律纠纷与合伙纠纷，切勿为了微薄利益卷入官司导致本金受困。",
      "wealthEn": "Audit contracts ruthlessly to forestall legal entanglements; settle commercial disputes amicably to preserve balance-sheet health.",
      "relationshipZh": "家不是讲理争胜负的法庭，放下谁对谁错的胜负欲，多给予情绪价值与理解，争端自解。",
      "relationshipEn": "Relinquish the urge to prove moral supremacy in arguments; emotional empathy and graceful conciliation restore harmony.",
      "actionGuidanceZh": "【宜】：作事谋始、求同存异、适度让步、平息纷争。【忌】：好勇斗狠、锱铢必较、对簿公堂、固执己见。",
      "actionGuidanceEn": "[Favorable]: Thoughtful beginnings, diplomatic concession, resolving disputes. [Taboo]: Combative posturing, vindictive lawsuits, bitter pride."
    }
