      "wealthEn": "Favorable for syndicated investments and joint ventures; vet counterparty integrity rigorously and structure clear mutual upside.",
      "relationshipZh": "真诚相待、毫无保留的信任是亲密关系的基石；尽早表明心意与确立关系，切忌脚踏两只船。",
      "relationshipEn": "Unconditional sincerity and transparent vulnerability cement long-term devotion; commit decisively without ambiguous hesitation.",
      "actionGuidanceZh": "【宜】：真诚结盟、主动亲近、互利共赢、果断同行。【忌】：迟疑观望、见异思迁、口蜜腹剑、自命清高。",
      "actionGuidanceEn": "[Favorable]: Early alignment, reciprocal loyalty, transparent partnership. [Taboo]: Tardy commitment, two-faced deceit, aloof detachment."
