      "wealthEn": "Strict regulatory and tax compliance; stay far from legal gray areas, as procedural rectitude protects principal from catastrophic forfeiture.",
      "relationshipZh": "亲密关系中亦当保持相敬如宾的分寸感，尊重对方的隐私与底线，严禁因过于熟络而肆无忌惮地伤害对方。",
      "relationshipEn": "Maintain courteous respect even in intimacy; honor personal boundaries and refrain from taking affection for granted.",
      "actionGuidanceZh": "【宜】：恪守规矩、谨言慎行、谦逊明礼、知止履险。【忌】：恃才傲物、僭越放肆、轻慢上司、踩踏红线。",
      "actionGuidanceEn": "[Favorable]: Strict protocol, impeccable etiquette, cautious navigation. [Taboo]: Reckless overfamiliarity, violating hierarchy, breaching boundaries."
