      "philosophyZh": "卦名【地天泰】，卦象由坤（地）与乾（天）上下相合而成，坤阴下降、乾阳上升，天地交感。核心重点在于【交泰通畅与协同共盛】——阴阳相交，上下通畅，乃万物繁茂昌盛之黄金时期；核心在于抓住时代红利大展宏图、推行变革、广聚英才；但须深知‘无平不陂、无往不复’，在全盛之时布局过冬防线。",
