      "actionGuidanceZh": "【宜】：俭德辟难、韬光养晦、坚守正道、固守底牌。【忌】：同流合污、逆势硬拼、怨天尤人、急功近利。",
      "actionGuidanceEn": "[Favorable]: Frugal preservation, moral steadfastness, strategic retreat. [Taboo]: Compromising ethics, desperate confrontations, bitter fretting."
