      "philosophyZh": "卦名【天火同人】，卦象由乾（天）与离（火）上下相合而成，天下有火，通明无私。核心重点在于【跨界结盟与天下大同】——火性炎上与天道相契，象征光明磊落、出以公心之宏大格局；核心在于打破宗族小圈子与门户之见，在旷野天下广结天下英才；切忌拉帮结派或私相授受，唯公天下方能克险建功。",
