      "wealthEn": "Monumental capital reserves; allocate into perpetual trust structures, societal philanthropy, and institutional capital preservation.",
      "relationshipZh": "家庭富足而尊荣，但切莫因物质充裕而忽视精神交流；以谦和仁爱持家，弘扬良好纯正家风。",
      "relationshipEn": "Nurture emotional tenderness amidst material success; cultivate family legacy through humble manners and genuine affection.",
      "actionGuidanceZh": "【宜】：遏恶扬善、顺天休命、慷慨布施、持盈保泰。【忌】：为富不仁、挥霍无度、傲慢称霸、得意忘形。",
      "actionGuidanceEn": "[Favorable]: Championing virtue, generous philanthropy, humble stewardship. [Taboo]: Arrogant luxury, oppressive greed, careless ostentation."
