      "relationshipEn": "Treat your partner with reverent courtesy; listen with total presence and dissolve domestic ego battles before they spark.",
      "actionGuidanceZh": "【宜】：谦逊低调、平抑盈虚、厚德润物、退让包容。【忌】：狂妄炫耀、好为人师、恃才矜贵、争名夺利。",
