      "philosophyZh": "卦名【雷地豫】，卦象由震（雷）与坤（地）上下相合而成，雷破地出，万物欢欣。核心重点在于【欢欣共鸣与顺民动员】——春雷震荡大地，生机蓬勃勃发，象征顺应民心民意之巨大感召力；核心在于顺天应人兴办大事、以文化艺术与美好愿景激发团队内在热情；但须警惕‘溺于享乐、怠忽政事’。",
