      "wealthEn": "Trend-following discipline; align capital with validated momentum rather than trying to catch falling knives with stubborn hubris.",
      "relationshipZh": "多倾听并尊重伴侣的决定与生活偏好，学会适度顺应对方，在和谐互动中收获彼此长久的愉悦。",
      "relationshipEn": "Adapt gracefully to your partner's emotional rhythms and preferences; harmonious compromise fosters mutual delight.",
      "actionGuidanceZh": "【宜】：顺应时势、择善而从、随机应变、放下执念。【忌】：固执己见、逆天而行、抗拒变革、自以为是。",
      "actionGuidanceEn": "[Favorable]: Agile adaptation, following wisdom, open-minded alignment. [Taboo]: Rigid obstinacy, fighting market trends, defensive denial."
