      "wealthEn": "Ruthlessly write off toxic assets and unprofitable operations; plug financial leaks immediately to re-anchor solvency.",
      "relationshipZh": "正视亲密关系中长期积压的心结、猜疑或家庭不良陋习，开诚布公长谈，彻底疗愈过往创伤。",
      "relationshipEn": "Directly address simmering resentments and unhealed family baggage; transparent, compassionate truth-telling cleanses emotional toxicity.",
      "actionGuidanceZh": "【宜】：拨乱反正、深挖积弊、果断革除、振衰起敝。【忌】：养痈遗患、粉饰太平、拖延逃避、姑息养奸。",
      "actionGuidanceEn": "[Favorable]: Root-cause remediation, decisive surgery, rigorous rehabilitation. [Taboo]: Whitewashing decay, procrastinating, indulging vice."
