      "wealthEn": "Macro thematic investing over short-term noise; align asset allocation with generational secular trends and policy shifts.",
      "relationshipZh": "以成熟理性的风度给予伴侣精神指引与情绪依靠，成为对方心中最值得信赖与仰望的精神灯塔。",
