      "philosophyZh": "卦名【山火贲】，卦象由艮（山）与离（火）上下相合而成，山下有火，草木蒙辉。核心重点在于【适度修饰与返璞归真】——文明礼仪与外观包装可增辉添彩，但必须有实质内核相承载；核心在于先质后文、适可而止，切忌华而不实、买椟还珠；最高境界乃是‘白贲无咎’，洗尽铅华始见真醇。",
      "philosophyEn": "[Core Focus: Elegant Branding & True Authenticity]: Upper Mountain over lower Fire. Prime directive: enhance substance with refined aesthetics, but never substitute packaging for intrinsic value. Pristine simplicity (Bai Ben) remains the ultimate elegance.",
