      "actionGuidanceZh": "【宜】：适度修饰、注重礼节、先实质后包装、返璞归真。【忌】：买椟还珠、虚荣浮夸、金玉其外、以辞害意。",
      "actionGuidanceEn": "[Favorable]: Refined presentation, authentic substance, gracious manners. [Taboo]: Shallow vanity, deceptive hype, prioritizing style over truth."
