      "philosophyZh": "卦名【山地剥】，卦象由艮（山）与坤（地）上下相合而成，高山附地，五阴剥一阳。核心重点在于【防范溃败与退守留存】——阴盛阳衰，大势崩解，基础已被掏空；核心在于顺天休命、全面防御，切忌盲目逆势投资或强行决战；保住核心元神与关键火种（硕果不食），以待来年东山再起。",
      "philosophyEn": "[Core Focus: Controlled Deconstruction & Seed Preservation]: Upper Mountain over lower Earth. Prime directive: manage orderly contraction when foundational structures erode. Refrain from aggressive gambits; safeguard core assets (the unconsumed fruit).",
