      "philosophyZh": "卦名【地雷复】，卦象由坤（地）与震（雷）上下相合而成，地中雷鸣，一阳来复。核心重点在于【触底反弹与微阳复苏】——极阴之后一阳初生，如同冬至阳气潜萌；核心在于安息休整、保全脆弱萌芽，万万不可揠苗助长；顺应‘七日来复’之自然节律，休养生息，等待势能自发裂变。",
      "philosophyEn": "[Core Focus: Bottoming Out & Germinating New Cycles]: Upper Earth over lower Thunder. Prime directive: nurture the first faint spark of renewal after prolonged exhaustion. Do not force premature scale; let the fragile new cycle root itself organically.",
