      "careerEn": "Deliver verified value through unpretentious excellence; reject unethical shortcuts and corporate politics to secure unassailable reputation.",
      "wealthZh": "只赚合情合理合规的明白钱，远离一切暴利诱惑与非法传销旁氏骗局；心安理得，财富自然绵长。",
      "wealthEn": "Earn legitimate, transparent returns; immunize yourself against get-rich-quick Ponzi schemes and predatory windfalls.",
      "relationshipZh": "以毫无算计的赤子之心坦诚相对，展现真实的自我，不伪装不欺瞒，收获纯粹真挚的灵魂伴侣。",
      "relationshipEn": "Approach love with childlike sincerity; discard manipulative games, and let unfeigned authenticity build enduring intimacy.",
      "actionGuidanceZh": "【宜】：光明坦荡、循规蹈矩、敬畏常理、返璞归真。【忌】：投机取巧、心存侥幸、妄图捷径、背信弃义。",
      "actionGuidanceEn": "[Favorable]: Absolute candor, adherence to principle, natural rectitude. [Taboo]: Speculative shortcuts, devious manipulation, wishful thinking."
