      "philosophyEn": "[Core Focus: Monumental Accumulation & Deep Moat Building]: Upper Mountain over lower Heaven. Prime directive: gather vast reservoirs of wisdom, capital, and strategic talent. Restrain premature action until overwhelming capacity guarantees triumph.",
