      "wealthEn": "Prune wasteful consumption; invest capital into physical wellness, nutritious living, and high-quality educational inputs.",
      "relationshipZh": "相处时多给予对方温和鼓励的良言善语，戒除伤人的恶言恶语；共同营造健康养生与起居规律的家庭环境。",
      "relationshipEn": "Feed your partner's soul with uplifting affirmations; eliminate corrosive sarcasm and cultivate restful living habits together.",
      "actionGuidanceZh": "【宜】：节制饮食、谨饬言语、自求口实、养德培元。【忌】：口不择言、暴饮暴食、玩物丧志、放纵私欲。",
      "actionGuidanceEn": "[Favorable]: Discerning consumption, verbal discretion, wholesome habits. [Taboo]: Reckless gossiping, gluttonous excess, toxic consumption."
