      "philosophyZh": "卦名【泽风大过】，卦象由兑（泽）与巽（风）上下相合而成，泽灭木顶，栋桡之象。核心重点在于【极限抗压与孤勇破局】——承载超常规之重负，栋梁不堪其重而弯曲；核心在于君子独立不惧、遁世无闷，需以大魄力推行非常之举；切忌墨守成规或惊慌失措，唯有置之死地而后生之大勇方能扭转乾坤。",
      "philosophyEn": "[Core Focus: Crisis Load-Bearing & Extraordinary Courage]: Upper Lake over lower Wind. Prime directive: shoulder massive transitional stress when structural pillars bend. Act with unconventional boldness and unshakeable fortitude to transcend deadlock.",
