      "wealthEn": "Debt structures or balance-sheet commitments face critical strain; execute immediate balance-sheet restructuring before collapse.",
      "relationshipZh": "共同面对重大外部风暴（如家庭变故或巨额经济危机），彼此紧握双手患难与共，做彼此最坚固的依靠。",
      "relationshipEn": "Stand shoulder-to-shoulder through severe life storms; withstand external pressures by anchoring each other with fierce loyalty.",
      "actionGuidanceZh": "【宜】：独立不惧、敢破敢立、果断断腕、力挽狂澜。【忌】：优柔寡断、墨守成规、心理崩溃、推卸责任。",
      "actionGuidanceEn": "[Favorable]: Radical courage, bold unconventional action, bearing stress. [Taboo]: Paralyzed indecision, rigid dogmatism, buckling under duress."
