      "wealthEn": "Align investment capital with sovereign policy tailwinds and technological revolutions; ride mega-trends with disciplined custody.",
      "relationshipZh": "彼此像两盏明灯互相照耀辉映，在互相崇拜与柔情依恋中保持温和包容，避免情绪暴躁引发口角。",
      "relationshipEn": "Illuminate each other's finest qualities; balance intense passion with gentle softness, avoiding emotional flare-ups.",
      "actionGuidanceZh": "【宜】：依附正道、借势赋能、柔顺中正、继明照四方。【忌】：傲慢孤立、暴烈冲动、急火攻心、脱离正轨。",
      "actionGuidanceEn": "[Favorable]: Strategic allegiance, enlightened adherence, cultivating gentle warmth. [Taboo]: Arrogant isolation, volcanic temper, reckless burnout."
