      "philosophyZh": "卦名【泽山咸】，卦象由兑（泽）与艮（山）上下相合而成，少男少女，山泽通气。核心重点在于【无心感应与同频共振】——天地感而万物化生，圣人感人心而天下和平；核心在于放下机心与功利计算，以虚静真诚之心接纳外界；心诚则灵，以毫无防设之诚恳唤起全方位深层共鸣。",
