      "wealthEn": "Classic buy-and-hold value compounding; back durable cash cows with enduring moats and let the flywheel turn without interruption.",
      "relationshipZh": "平平淡淡才是真，在柴米油盐之琐碎中坚守最初之誓言，以恒久如一之责任感守护家庭长治久安。",
      "relationshipEn": "Embrace the enduring grace of everyday domestic life; anchor romantic partnership in unflinching reliability and fidelity.",
      "actionGuidanceZh": "【宜】：立不易方、持之以恒、耐住寂寞、久久为功。【忌】：见异思迁、朝令夕改、浮躁跟风、半途而废。",
      "actionGuidanceEn": "[Favorable]: Resolute consistency, patient compounding, steadfast commitment. [Taboo]: Fickle pivoting, chasing fads, abandonment midway."
