      "wealthEn": "Flush with capital: resist the temptation of reckless mega-acquisitions; enforce disciplined capital allocation and maintain fat margins of safety.",
      "relationshipZh": "切莫在家庭中以强权命令压制伴侣，学会收敛锋芒，多展现体贴温柔，家和方能万事兴隆。",
      "relationshipEn": "Renounce forceful dominance at home; allow your partner equal sovereignty and express strength through patient protection.",
      "actionGuidanceZh": "【宜】：正大光明、克制强力、遵纪守礼、内敛蓄势。【忌】：恃强凌弱、盲动蛮干、刚愎自用、触碰红线。",
      "actionGuidanceEn": "[Favorable]: Righteous restraint, institutional humility, disciplined power. [Taboo]: Bullying arrogance, reckless charging, breaking fences."
