      "philosophyZh": "卦名【火地晋】，卦象由离（火）与坤（地）上下相合而成，日出地上，光明遍照。核心重点在于【乘势跃升与昭彰德业】——日升大地，万物生辉，象征才华大白于天下之跃升期；核心在于依托正规体制与明主贵人，以昭明德业获得破格提拔；‘康侯用锡马蕃庶’，乘时代之风顺水推舟迅速崛起。",
