      "philosophyZh": "卦名【地火明夷】，卦象由坤（地）与离（火）上下相合而成，光明入地，暗夜无光。核心重点在于【暗局隐忍与韬光养晦】——身处昏暗乱局、受制于暴虐小人；核心在于内心光明如炬而不灭，外表装痴守拙、敛藏锋芒；‘箕子之明夷，利贞’，在至暗时刻以极致隐忍保全性命，静待黎明破晓。",
      "philosophyEn": "[Core Focus: Guarding Inner Light in Darkness & Tactical Concealment]: Upper Earth over lower Fire. Prime directive: hide brilliance beneath humble simplicity when malevolent forces dominate. Preserve inner integrity silently; endure the night until dawn.",
