      "philosophyZh": "卦名【火泽睽】，卦象由离（火）与兑（泽）上下相合而成，火上腾泽下流，背道而驰。核心重点在于【求同存异与逆向互补】——万物因相异而生化，二女同居其志不同；核心在于包容差异、在冲突对立中寻找潜在互补性；切忌强求一致或情绪化对抗，小事吉而大事慎，借相异之势成非常之局。",
