    "modernInterpretation": {
      "philosophyZh": "卦名【山泽损】，卦象由艮（山）与兑（泽）上下相合而成，山下有泽，损下益上。核心重点在于【欲望管理与战略减负】——断舍离冗余欲望、内耗事务与负资产，以主动节制换取基底稳固；‘惩忿窒欲，损己利人’，以真诚纯粹之心结盟合作，看似眼前有损，实则为长久跃升蓄积不可估量的战略福报。",
      "philosophyEn": "[Core Focus: Strategic Restraint & Elimination of Excess]: Upper Mountain over lower Lake. Prime directive: proactively prune redundant desires, friction, and unproductive liabilities. Voluntary restraint and authentic service to core allies turn apparent short-term sacrifice into enduring compounding.",
      "careerZh": "主动精简边缘不赚钱业务，砍掉冗余汇报与低效社交；把全部精力聚焦于核心业务，损虚浮以益实效。",
      "careerEn": "Prune marginal, loss-making projects and bureaucratic bloat; concentrate resources onto core profit engines with disciplined focus.",
      "wealthZh": "严格压缩非必要非刚性消费开支，主动偿还高息负债，以小步储蓄与资产减负构筑无懈可击的安全边际。",
      "wealthEn": "Cut discretionary burn, pay down expensive debt, and accept smaller immediate margins to build an unbreachable margin of safety.",
      "relationshipZh": "克制自己的脾气与任性要求，多为对方着想付出；在关键时刻主动退让一步，反而收获深情回馈。",
      "relationshipEn": "Restrain self-centered demands and curb emotional reactivity; voluntary sacrifice for your partner's wellbeing binds the bond deeply.",
      "actionGuidanceZh": "【宜】：惩忿窒欲、战略减负、去粗取精、诚意奉献。【忌】：放纵贪欲、盲目铺摊、计较得失、虚掷精力。",
      "actionGuidanceEn": "[Favorable]: Strategic pruning, controlling temper, pruning liabilities, sincere devotion. [Taboo]: Unchecked hedonism, hoarding deadweight, petty scorekeeping."
    }
