      "wealthEn": "Massive capital inflows; reinvest aggressively into core R&D, capacity expansion, and high-yield operational assets.",
      "relationshipZh": "家庭条件全面提升，宜带全家享受生活、感恩回馈长辈与伴侣，让家庭成员共同分享时代红利与幸福。",
      "relationshipEn": "Celebrate material and emotional windfalls together; shower partner with gratitude and reinvest in family prosperity.",
      "actionGuidanceZh": "【宜】：乘胜追击、损上益下、见善则迁、大方分利。【忌】：小肚鸡肠、独吞战果、骄横放肆、固步自封。",
      "actionGuidanceEn": "[Favorable]: Aggressive reinvestment, sharing upside, swift self-correction. [Taboo]: Greedy hoarding, monopolizing credit, arrogant complacency."
