      "philosophyZh": "卦名【泽地萃】，卦象由兑（泽）与坤（地）上下相合而成，泽水汇地，聚合荟萃。核心重点在于【资源聚合与戒备不测】——天下英才、资本与海量注意力向此高度聚集；核心在于‘聚以正道’，以崇高理想与敬畏之心统领众人；‘修除戎器，以戒不虞’，越是人多势众，越要修缮安保防范意外事故与踩踏。",
      "philosophyEn": "[Core Focus: Mass Mobilization & Contingency Security]: Upper Lake over lower Earth. Prime directive: convene capital, talent, and public energy around legitimate moral purpose. As scale expands, fortify defenses to prevent chaos and unforeseen catastrophe.",
