      "wealthEn": "Pool capital via formal syndicate or strategic funding rounds; install third-party escrow and independent audits to govern scale.",
      "relationshipZh": "家族大团聚或亲朋好友高朋满座，展现热情好客与大方气度，在欢乐相聚中增进宗亲情谊与家族凝聚力。",
      "relationshipEn": "Host warm family reunions and foster community fellowship; spread magnanimous hospitality and celebrate shared bonds.",
      "actionGuidanceZh": "【宜】：聚众以正、广聚贤能、完善安保、居安思危。【忌】：乌合之众、缺乏防备、利益不公、狂热盲动。",
      "actionGuidanceEn": "[Favorable]: Principled aggregation, elite community building, rigorous defenses. [Taboo]: Disorganized mobs, lax security, inequitable spoils."
