    "judgmentEn": "Towns may shift, but the well remains unchanged; neither loss nor gain. Coming and going, all draw from the well. If nearly reached, but rope breaks before bucket is drawn, misfortune ensues.",
    "tuanZh": "《彖》曰：水风井，天地之道，刚柔节也。",
    "tuanEn": "Tuan: The Well / Inexhaustible Resource, the harmonious path of heaven and earth balancing firm and yielding.",
    "greatXiangZh": "木上有水，井；君子以劳民劝相。",
    "greatXiangEn": "Water rises above wood: The Well. Thus the noble person encourages the people and urges mutual support.",
