      "wealthEn": "Allocate into essential infrastructure, high-dividend utilities, and recurring cash-flow generators that produce in all seasons.",
      "relationshipZh": "感情像一口清澈的甘井，需要日常持续的理解与关爱来滋养维护，切莫因年久而疏于打理任其干涸。",
      "relationshipEn": "Treat love as a deep well requiring daily replenishment; tend to emotional intimacy so the shared reservoir never dries out.",
      "actionGuidanceZh": "【宜】：深挖内潜、持续供给、修葺底座、慎终如始。【忌】：功亏一篑、荒废主业、浅尝辄止、竭泽而渔。",
      "actionGuidanceEn": "[Favorable]: Deepening core competence, continuous value delivery, finishing strong. [Taboo]: Superficial dabbling, breaking the vessel at the rim."
