    "judgmentEn": "On the appointed day comes belief. Sublime success, furthering through perseverance. Regret vanishes.",
    "tuanZh": "《彖》曰：泽火革，天地之道，刚柔节也。",
    "tuanEn": "Tuan: Revolution / Timely Transformation, the harmonious path of heaven and earth balancing firm and yielding.",
    "greatXiangZh": "泽中有火，革；君子以治历明时。",
    "greatXiangEn": "Fire burns within the lake: Revolution. Thus the noble person calculates calendars and clarifies seasons.",
