      "relationshipZh": "彻底打破两人过往陈旧甚至有害的相处旧模式，重新订立情感契约与家庭分工，以全新面貌开启关系新篇章。",
      "relationshipEn": "Reinvent stagnant relationship patterns; clear the air courageously and draft a renewed relational covenant for the future.",
      "actionGuidanceZh": "【宜】：顺天应人、大刀阔斧、树立公信、破旧立新。【忌】：因循守旧、拖泥带水、盲目妄动、失信于人。",
