    "judgmentZh": "亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。",
    "judgmentEn": "Success. Thunder approaches with terror, followed by joyous laughter. Shock terrifies for a hundred leagues, yet the master does not spill the sacrificial spoon.",
    "tuanZh": "《彖》曰：震为雷，天地之道，刚柔节也。",
    "tuanEn": "Tuan: The Arousing Thunder / Shockwave, the harmonious path of heaven and earth balancing firm and yielding.",
    "greatXiangZh": "洊雷，震；君子以恐惧修省。",
    "greatXiangEn": "Doubled thunder bursts forth: The Arousing. Thus the noble person examines character with reverent awe.",
