      "wealthEn": "Financial markets panic in flash crash: preserve emotional equanimity, refrain from panic selling, and exploit mispriced panic.",
      "relationshipZh": "家庭遭遇突发意外变故，作为顶梁柱切莫惊慌失措；以镇定的臂膀撑起全家希望，迅速采取有效措施稳住后方。",
      "relationshipEn": "When unexpected crisis hits home, be the calm center of the storm; provide decisive, reassuring leadership to steady your family.",
      "actionGuidanceZh": "【宜】：临危不惧、敬畏天道、反躬自省、镇定持重。【忌】：惊慌失措、举止失据、手足无措、自乱阵脚。",
      "actionGuidanceEn": "[Favorable]: Majestic composure, prompt crisis containment, sober self-audit. [Taboo]: Screaming panic, knee-jerk overreaction, paralyzed fear."
