      "wealthEn": "Financial compounding like marathon runner; build wealth via programmatic savings, productive real assets, and steady patience.",
      "relationshipZh": "恋爱与婚姻的最佳典范；从相识、相知、相恋到明媒正娶，按部就班合乎礼义，感情深厚、天长地久。",
      "relationshipEn": "Classic archetype of honorable marriage; honor traditional courting stages, deepen mutual respect, and build lasting domestic bliss.",
      "actionGuidanceZh": "【宜】：循序渐进、按部就班、笃定踏实、守礼慎行。【忌】：急功近利、走捷径、拔苗助长、图谋暴发。",
      "actionGuidanceEn": "[Favorable]: Methodical cadence, dignified protocol, steady organic compounding. [Taboo]: Impatient shortcuts, cutting corners, flash-in-the-pan rushing."
