    "judgmentZh": "亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。",
    "judgmentEn": "Success, furthering through perseverance. Small matters permissible, grand enterprises not permissible. The bird in flight leaves its cry: not suited to ascend, suited to descend; grand good fortune.",
    "tuanZh": "《彖》曰：雷山小过，天地之道，刚柔节也。",
    "tuanEn": "Tuan: Preponderance of the Small / Conscientious Caution, the harmonious path of heaven and earth balancing firm and yielding.",
    "greatXiangZh": "山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。",
    "greatXiangEn": "Thunder echoes over the mountain: Small Excess. Thus the noble person errs on the side of reverence in conduct, sorrow in mourning, frugality in spending.",
