    "specialLineZh": null,
    "specialLineEn": null,
    "modernInterpretation": {
      "philosophyZh": "卦名【水火既济】，卦象由坎（水）与离（火）上下相合而成，水在火上，水火烹饪。核心重点在于【居安思危与防患未然】——六爻皆得正位，功德圆满，全盘达到最完美平衡；但易经千古警诫‘初吉终乱’；处于巅峰圆满之时刻，必须如履薄冰修补堤防，严防因懈怠而陷入混乱崩解。",
      "philosophyEn": "[Core Focus: Apex Equilibrium & Vigilant Preservation]: Upper Water over lower Fire. All lines in proper place. Prime directive: sustain peak order with relentless vigilance. Equilibrium is fragile; the moment perfection is attained, entropy begins to stalk.",
      "careerZh": "大项目圆满收官或业绩达到全胜，切莫开庆功宴忘乎所以；立即复盘总结风险、建立长效维护机制，防范反弹。",
      "careerEn": "Project achieves triumphant delivery: celebrate briefly, then shift immediately into maintenance protocols and proactive bug prevention.",
      "wealthZh": "财富达到理想目标，立即锁仓防守、分散配置；停止盲目进取，守成重于开拓，防范盛极之下的资产折损。",
      "wealthEn": "Financial goals attained: de-risk aggressively and diversify into resilient endowments; prioritize wealth preservation over reckless upside chasing.",
      "relationshipZh": "家庭美满幸福到了极点，珍惜眼前的每分每秒；细心体察伴侣日常微小情绪变化，用心维系长久的温润甜蜜。",
      "relationshipEn": "Cherish domestic perfection with mindful gratitude; continuously invest in subtle emotional connection to prevent drifting into boredom.",
      "actionGuidanceZh": "【宜】：居安思危、防患未然、细心维护、持盈保泰。【忌】：大功告成而懈怠、得意忘形、盲目自满、疏于看护。",
      "actionGuidanceEn": "[Favorable]: Vigilant maintenance, contingency prep, preserving order. [Taboo]: Victorious complacency, relaxation of standards, hubristic neglect."
    }
